(async () => {
  const pages = figma.root.children;
  const result = {};

  for (const page of pages) {
    await page.loadAsync();

    function extractText(node) {
      let texts = [];
      if (node.type === 'TEXT') {
        texts.push({ name: node.name, characters: node.characters });
      }
      if ('children' in node) {
        for (const child of node.children) {
          texts.push(...extractText(child));
        }
      }
      return texts;
    }

    function summarizeNode(node) {
      return {
        id: node.id,
        name: node.name,
        type: node.type,
        childrenCount: 'children' in node ? node.children.length : 0
      };
    }

    result[page.name] = {
      id: page.id,
      topNodes: page.children.map(summarizeNode),
      texts: extractText(page)
    };
  }

  return result;
})()

(async () => {
  const componentsPage = figma.root.children.find(p => p.name.includes("02 · Components"));
  const mediaPage = figma.root.children.find(p => p.name.includes("04 · Media"));
  const foundationsPage = figma.root.children.find(p => p.name.includes("01 · Foundations"));

  await componentsPage.loadAsync();
  await mediaPage.loadAsync();
  await foundationsPage.loadAsync();

  function getDetails(node) {
    if (node.type === 'COMPONENT' || node.type === 'COMPONENT_SET' || node.type === 'FRAME') {
      return {
        id: node.id,
        name: node.name,
        type: node.type,
        width: node.width,
        height: node.height,
        children: 'children' in node ? node.children.map(c => ({ id: c.id, name: c.name, type: c.type })) : []
      };
    }
    return null;
  }

  const components = componentsPage.children[0].children.map(getDetails).filter(Boolean);
  const media = mediaPage.children[0].children.map(getDetails).filter(Boolean);

  return {
    components,
    media
  };
})()

(async () => {
  const mediaPage = figma.root.children.find(p => p.name.includes("04 · Media"));
  await mediaPage.loadAsync();

  const map = {};
  function walk(node) {
    if (node.name.startsWith("Logo_") || node.name.startsWith("Illustration_") || node.name.startsWith("Card_") || node.name.startsWith("Promo_") || node.name.startsWith("Avatar_") || node.name.startsWith("Merchant_") || node.name.startsWith("Barcode_") || node.name.startsWith("Icon_") || node.name.startsWith("Status Bar") || node.name.startsWith("Home Indicator")) {
      map[node.name] = { id: node.id, type: node.type, width: node.width, height: node.height };
    }
    if ('children' in node) {
      for (const c of node.children) walk(c);
    }
  }
  walk(mediaPage);

  const compPage = figma.root.children.find(p => p.name.includes("02 · Components"));
  await compPage.loadAsync();
  walk(compPage);

  return map;
})()

