(async () => {
  const mediaPage = figma.root.children.find(p => p.name.includes("04 · Media"));
  await mediaPage.loadAsync();

  const map = {};
  for (const group of mediaPage.children[0].children) {
    if (group.type === 'FRAME') {
      for (const child of group.children) {
        if (child.type === 'FRAME') {
          const comp = child.children.find(c => c.type === 'COMPONENT');
          if (comp) {
            map[comp.name] = comp.id;
          }
        }
      }
    }
  }

  const compPage = figma.root.children.find(p => p.name.includes("02 · Components"));
  await compPage.loadAsync();
  const shell = compPage.children[0].children.find(c => c.name === 'Shell');
  if (shell) {
    for (const c of shell.children) {
      if (c.type === 'COMPONENT') {
        map[c.name] = c.id;
      }
    }
  }
  const button = compPage.children[0].children.find(c => c.name === 'Button');
  if (button) map['Button'] = button.id;
  const textField = compPage.children[0].children.find(c => c.name === 'Text Field');
  if (textField) map['Text Field'] = textField.id;

  return map;
})()

