      actions: [{
        type: "NODE",
        destinationId: targetId,
        navigation: "NAVIGATE",
        transition: null
      }]
    }];
  }

  // 1. 01_Get_Started -> Get Started button -> 02_Home
  const btn1 = f1.children.find(c => c.name === "Button");
  setClickReaction(btn1, f2.id);

  // 2. 02_Home -> open balance / See all -> 03_Wallet; new payment -> 05_Payment
  const balCard = findChildByName(f2, "Balance_Card");
  setClickReaction(balCard, f3.id);

  const seeAll = f2.children.find(c => c.type === "TEXT" && c.characters === "See all");
  setClickReaction(seeAll, f3.id);

  const fab = findChildByName(f2, "Fab_New_Payment");
  setClickReaction(fab, f5.id);

  // 3. 03_Wallet -> Back -> 02_Home; add card -> 04_Add_Card
  const backIcon3 = f3.children.find(c => c.name === "Icon_Back");
  setClickReaction(backIcon3, f2.id);

  const addCardIcon3 = f3.children.find(c => c.name === "Icon_Add_Card");
  setClickReaction(addCardIcon3, f4.id);

  // 4. 04_Add_Card -> Add new card / close -> 03_Wallet
  const sheet4 = findChildByName(f4, "Bottom_Sheet");
  const closeIcon4 = findChildByName(sheet4, "Icon_Close");
  setClickReaction(closeIcon4, f3.id);

  const btnAdd4 = sheet4 ? sheet4.children.find(c => c.name === "Button") : null;
  setClickReaction(btnAdd4, f3.id);

  // 5. 05_Payment -> Pay now -> 06_Receipt; Cancel -> 02_Home
  const cancel5 = f5.children.find(c => c.type === "TEXT" && c.characters === "Cancel");
  setClickReaction(cancel5, f2.id);

  const btnPay5 = f5.children.find(c => c.name === "Button");
  setClickReaction(btnPay5, f6.id);

  // 6. 06_Receipt -> Home -> 02_Home
  const btnHome6 = f6.children.find(c => c.name === "Button");
  setClickReaction(btnHome6, f2.id);

  return {
    f1: f1.id,
    f2: f2.id,
    f3: f3.id,
    f4: f4.id,
    f5: f5.id,
    f6: f6.id,
    message: "Prototype interactions wired successfully!"
  };
})()
